pub fn _json_get_float(v: JsonValue, key: []const u8) f64 {
    switch (v) { .object => |o| if (o.get(key)) |it| switch (it) {
        .float => |f| return f, .integer => |n| return @floatFromInt(n), else => {} }, else => {} }
    return 0.0;
