                var _bi: usize = 0;
                while (_bi < _cl) {
                    var _slices: [1][]u8 = .{_bb[_bi..]};
                    const _rn = _srv_rd.interface.readVec(&_slices) catch break;
                    if (_rn == 0) break;
                    _bi += _rn;
                }
