        var f = _RFrag{ .start = a.start }; var i: u8 = 0;
        for (a.outs[0..a.n]) |o| { f.outs[i] = o; i += 1; }
        for (b.outs[0..b.n]) |o| { f.outs[i] = o; i += 1; }
        f.n = i; return f;
    }
};
pub const _RC = struct {
