        while (result != null) {
            const next = try c.parsePiece() orelse break;
            c.patchFrag(result.?, next.start);
            result = _RFrag{ .start = result.?.start, .outs = next.outs, .n = next.n };
        }
        return result;
    }
    pub fn parseAlt(c: *_RC) error{OutOfMemory}!?_RFrag {
